    "summary": "Kiệt tác văn học thiếu nhi Nhật Bản. Cáo mẹ ếm bùa biến bàn tay cáo con thành tay người để vào tiệm mua đôi găng len ấm áp xua tan giá lạnh.",
    "isPictureBook": true,
    "isMultiChapter": true,
